// Split "headers + body" (retrieve mode BOTH) into status code and body.
// A value that does not start with HTTP/ is the transport-error marker (no HTTP response).
// Loops so proxy CONNECT header blocks or 1xx blocks are skipped.
function split(v) {
  var code = 0, body = String(v);
  while (body.indexOf('HTTP/') === 0) {
    var m = /^HTTP\/[0-9.]+\s+([0-9]{3})/.exec(body);
    code = m ? parseInt(m[1], 10) : 0;
    var i = body.search(/\r?\n\r?\n/);
    if (i < 0) { body = ''; break; }
    body = body.substring(i).replace(/^\r?\n\r?\n/, '');
  }
  return {code: code, body: body};
}
function hint(code, extra) {
  if (code === 0) return 'No HTTP response (DNS, TLS, timeout or connection refused)';
  if (code === 401) return 'HTTP 401: authentication failed, check token ID and secret';
  if (code === 403) return 'HTTP 403: access denied, check Auditor ACL on /system/status for both user and token';
  if (code === 404) return 'HTTP 404: endpoint not found, check URL and PDM version' + (extra || '');
  return 'HTTP ' + code + ': unexpected response';
}

// Output: the original PDM JSON ({"data":{...}}) plus "http": <status code>,
// or {"http":<code>,"error":"<reason>"} when the request failed.
try {
  var r = split(value);
  if (r.code !== 200) return JSON.stringify({http: r.code, error: hint(r.code)});
  var b;
  try { b = JSON.parse(r.body); } catch (e) { b = null; }
  if (!b || typeof b !== 'object' || Array.isArray(b)) {
    return JSON.stringify({http: 200, error: 'HTTP 200 but response is not a JSON object, check URL'});
  }
  b.http = 200;
  return JSON.stringify(b);
} catch (e) {
  return JSON.stringify({http: 0, error: 'Preprocessing failure: ' + e});
}

// 1 = HTTP 200 and the core fields used by the triggers are valid. Used to gate all other triggers.
var d;
try { var o = JSON.parse(value); if (o.http !== 200) return 0; d = o.data; } catch (e) { return 0; }
function n(x) { return typeof x === 'number' && isFinite(x) && x >= 0; }
if (!d || !n(d.cpu) || !n(d.uptime)) return 0;
if (!d.memory || !n(d.memory.total) || !n(d.memory.used) || d.memory.total === 0) return 0;
if (!d.root || !n(d.root.total) || !n(d.root.used) || d.root.total === 0) return 0;
return 1;

// 1 = every field this template reads is present and sane. Stricter than pdm.api.available.
var d;
try { var o = JSON.parse(value); if (o.http !== 200) return 0; d = o.data; } catch (e) { return 0; }
function n(x) { return typeof x === 'number' && isFinite(x) && x >= 0; }
if (!d || !n(d.cpu) || !n(d.wait) || !n(d.uptime)) return 0;
if (!d.cpuinfo || !n(d.cpuinfo.cpus) || d.cpuinfo.cpus === 0 || typeof d.cpuinfo.model !== 'string') return 0;
if (!d.loadavg || d.loadavg.length < 3) return 0;
for (var i = 0; i < 3; i++) if (!n(d.loadavg[i])) return 0;
if (!d['current-kernel'] || typeof d['current-kernel'].release !== 'string') return 0;
var groups = ['memory', 'swap', 'root'];
for (var j = 0; j < groups.length; j++) {
  var g = d[groups[j]];
  if (!g || !n(g.total) || !n(g.used) || !n(g[groups[j] === 'root' ? 'avail' : 'free'])) return 0;
}
if (d.memory.total === 0 || d.root.total === 0) return 0;
return 1;

