// Output: {"http":<code>,"available":0|1,"data":{<field>:<newest valid value>},"error":"..."}
// For every field the newest non-null, non-negative value that is at most MAXAGE seconds old is used.
var MAXAGE = 600, SKEW = 60;
function empty(code, msg) {
  return JSON.stringify({http: code, available: 0, data: {}, error: msg});
}
try {
  var r = split(value);
  if (r.code !== 200) return empty(r.code, hint(r.code, ' (local RRD needs PDM 1.1+)'));
  var b;
  try { b = JSON.parse(r.body); } catch (e) { b = null; }
  if (!b || !Array.isArray(b.data)) return empty(200, 'HTTP 200 but RRD response has no data array, check URL');
  var now = Math.floor(Date.now() / 1000), newest = {}, out = {}, n = 0;
  for (var i = 0; i < b.data.length; i++) {
    var p = b.data[i];
    if (!p || typeof p.time !== 'number' || p.time > now + SKEW || now - p.time > MAXAGE) continue;
    for (var k in p) {
      if (k === 'time') continue;
      var x = p[k];
      if (typeof x !== 'number' || !isFinite(x) || x < 0) continue;
      if (!(k in newest) || p.time > newest[k]) {
        if (!(k in newest)) n++;
        newest[k] = p.time;
        out[k] = x;
      }
    }
  }
  if (n === 0) return empty(200, 'No RRD data point newer than 10 minutes, check clock sync and PDM version (1.1+)');
  return JSON.stringify({http: 200, available: 1, data: out});
} catch (e) {
  return empty(0, 'Preprocessing failure: ' + e);
}

