// Output: {"http":200,"notafter":<epoch>,"days":<days left>,"subject":"..","issuer":".."}
// or {"http":<code>,"error":"<reason>"} when the request failed or has no expiry date.
try {
  var r = split(value);
  if (r.code !== 200) return JSON.stringify({http: r.code, error: hint(r.code)});
  var b;
  try { b = JSON.parse(r.body); } catch (e) { b = null; }
  var c = b && Array.isArray(b.data) ? b.data[0] : null;
  if (!c || typeof c.notafter !== 'number') {
    return JSON.stringify({http: 200, error: 'HTTP 200 but response has no certificate expiry date, check URL'});
  }
  var now = Math.floor(Date.now() / 1000);
  return JSON.stringify({http: 200, notafter: c.notafter, days: Math.floor((c.notafter - now) / 86400),
